window.bookSummaryJSON = "<p>From Brandon Sanderson - the number-one <i>New York Times</i> best-selling author of <i>Words of Radiance</i>, co-author of Robert Jordan's Wheel of Time series and creator of the internationally best-selling Mistborn Trilogy - comes <i>Mitosis</i>, a short story set in the action-packed world of \"Steelheart: the Reckoners\" series. </p> <p>Epics still plague Newcago, but David and the Reckoners have vowed to fight back. Catch all the action before <i>Firefight</i>, the exciting sequel to <i>Steelheart</i>, comes to audio.</p>"; 
